const DEDUCT_THRESHOLD = 4.5;
const DEDUCT_HRS = 50 / 60;
const APP_URL = typeof window !== "undefined" ? window.location.origin : "";
const STORAGE_KEY = "mb_phone_identity";

const billable = (h) => h >= DEDUCT_THRESHOLD ? h - DEDUCT_HRS : h;
const fmtHrs = (h) => { if (!h || h <= 0) return "—"; const hr = Math.floor(h), mn = Math.round((h - hr) * 60); return `${hr}h ${mn}m`; };
const fmtMoney = (n) => "$" + (n || 0).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
const fmtTime = (ts) => { if (!ts) return "—"; const d = ts?.toDate ? ts.toDate() : new Date(ts); return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }); };
const fmtDate = (ts) => { if (!ts) return "—"; const d = ts?.toDate ? ts.toDate() : new Date(ts); return d.toLocaleDateString([], { month: "short", day: "numeric", year: "numeric" }); };
const fmtElapsed = (ms) => { const s = Math.floor(ms / 1000); return [Math.floor(s / 3600), Math.floor((s % 3600) / 60), s % 60].map(v => String(v).padStart(2, "0")).join(":"); };
const calcBillable = (i, o) => { if (!o) return 0; const r = (new Date(o) - new Date(i)) / 3600000; return r >= DEDUCT_THRESHOLD ? r - DEDUCT_HRS : r; };
const toDate = (ts) => ts?.toDate ? ts.toDate() : ts ? new Date(ts) : null;
const cleanPhone = (p) => p.replace(/\D/g, "");

function getWeekBounds() {
  const now = new Date(), day = now.getDay(), diff = day === 0 ? -6 : 1 - day;
  const mon = new Date(now); mon.setHours(0,0,0,0); mon.setDate(now.getDate() + diff);
  const sun = new Date(mon); sun.setDate(mon.getDate() + 6); sun.setHours(23,59,59,999);
  return { mon, sun };
}


